@import "typography";
@import "colours";
@import "buttons";
@import "header";
@import "footer";
@import "blog";
@import "a11y";
@import "search";
@import "forms";
@import "wp";
@import "blocks/blocks";

html {
  scrollbar-gutter: stable;
}

body {
  background-color: var(--col-white);
  min-block-size: 100svh;
}

@media (min-width: 992px) {
  .cols-lg-2 {
    columns: 2;
  }

  .cols-lg-3 {
    columns: 3;
  }
}

.sticky {
  position: sticky;
  top: 0; // var(--h-top);

  @media (min-width: 992px) {
    top: 0; //var(--h-top-desktop);
  }

  background-color: var(--col-white);
}

// Adjust fixed header when admin bar is present
.admin-bar header.fixed-top {
  top: 32px; // Admin bar height
}

.anchor {
  display: block;
  position: relative;
  top: calc(-1 * var(--h-top) - 1rem);
  visibility: hidden;

  @media (min-width: 992px) {
    top: calc(-1 * var(--h-top-desktop) - 1rem);
  }
}

section[id] {
  scroll-margin-top: 2rem;

  @media (min-width: 992px) {
    scroll-margin-top: 5.5rem;
  }
}

#breadcrumbs {
  font-size: var(--text-sm);

  a {
    text-decoration: none;
    font-weight: var(--fw-600);
    color: var(--col-brand-dark);
  }
}

.wp-block-group {
  &:not(.alignfull) {
    @extend .container;

    & .container {
      padding-inline: 0;
    }
  }
}

.container .container {
  padding-inline: 0;
}

.cb-gsap-fade {
  opacity: 0;
  visibility: hidden;
  transform: translate3d(0, 20px, 0);
  will-change: opacity, transform;
}

@media (prefers-reduced-motion: reduce) {
  .cb-gsap-fade {
    opacity: 1;
    visibility: visible;
    transform: none;
    will-change: auto;
  }
}

