.site-footer {
  position: relative;
  padding-block-start: 4rem;
  margin-top: clamp(4rem, 8vw, 7rem);
  background: var(--cb-forest);
  color: var(--cb-paper);
  // The curve below is 120vw wide, so it overhangs each side by 10vw. Without
  // this every page was wider than the viewport and scrolled sideways on a
  // phone. clip rather than hidden: it leaves the vertical axis visible, which
  // the curve needs because it sits above the footer's top edge.
  overflow-x: clip;

  &::before {
    content: "";
    position: absolute;
    top: calc(-10vw + 1px);
    left: 50%;
    display: inline-block;
    width: 120vw;
    height: 10vw;
    min-height: 65px;
    background-color: var(--cb-forest);
    vertical-align: middle;
    transform: translateX(-50%);
    mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1440 66' xml:space='preserve'><path d='M1440 66C1283.48 26.17 1019.4 0 720 0S156.52 26.17 0 66h1440z'/></svg>");
    mask-position: center bottom;
    mask-repeat: no-repeat;
    mask-size: 100% auto;
    -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1440 66' xml:space='preserve'><path d='M1440 66C1283.48 26.17 1019.4 0 720 0S156.52 26.17 0 66h1440z'/></svg>");
    -webkit-mask-position: center bottom;
    -webkit-mask-repeat: no-repeat;
    -webkit-mask-size: 100% auto;
  }

  &__spacer {
    height: 2rem;
  }

  &__main {
    position: relative;
    z-index: 1;
  }

  &__brand {
    margin-bottom: 2rem;

    @media (min-width: 992px) {
      margin-bottom: 0;
    }
  }

  &__logo {
    display: inline-block;
    color: var(--cb-paper);
    text-decoration: none;
  }

  &__logo-text {
    display: inline-block;
    font-size: clamp(2rem, 4vw, 3.2rem);
    font-weight: var(--fw-bold);
    letter-spacing: -0.06em;
    line-height: 1;

    span {
      color: var(--cb-emerald);
    }
  }

  h2 {
    margin: 0.45rem 0 0;
    color: var(--cb-paper);
    font-size: 1rem;
    font-weight: var(--fw-semibold);
  }

  &__nav {
    margin-bottom: 2rem;

    @media (min-width: 992px) {
      margin-bottom: 0;
    }
  }

  &__menu {
    padding: 0;
    margin: 0;
    list-style: none;

    li {
      padding: 0.2rem 0;
    }

    a {
      color: var(--cb-paper);
      font-size: 0.727272rem;
      text-decoration: none;
      transition: color 0.5s ease-out;

      &:hover,
      &:focus-visible {
        color: var(--cb-emerald);
      }
    }
  }

  &__social {
    display: flex;
    gap: 0.5rem;

    @media (min-width: 992px) {
      justify-content: flex-end;
    }

    // The anchor stays larger than the glyph so it keeps a comfortable tap
    // target (1.75rem = 38.5px at the 22px root, well over the 24px WCAG 2.5.8
    // minimum) while the icon itself sits in proportion to the 16px nav text
    // beside it. Previously both were 2rem, so the glyph filled the anchor and
    // rendered at 44px - nearly three times the body text.
    a {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 1.75rem;
      height: 1.75rem;
      color: var(--cb-paper);
    }

    svg {
      width: 1rem;
      height: 1rem;
      fill: currentColor;
    }

    a:hover,
    a:focus-visible {
      color: var(--cb-emerald);
    }
  }

  &__legal {
    position: relative;
    z-index: 1;
    padding-block: 2.5rem 1rem;
    color: rgba(255, 255, 255, 0.8);
    font-size: 0.636363rem;
  }

  // Statutory disclosure. Quieter than the copyright line - it has to be
  // present and legible, not prominent.
  &__legal-details {
    margin: 0.75rem 0 0;
    max-width: 62rem;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.6;
  }

  &__legal-links {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    justify-content: flex-end;

    a {
      color: inherit;
      text-decoration: none;
      transition: color 0.5s ease-out;

      &:hover,
      &:focus-visible {
        color: var(--cb-emerald);
      }
    }
  }
}

@media (max-width: 991.98px) {
  .site-footer {
    &__legal {
      .row {
        flex-direction: column;
        gap: 0.5rem;
      }
    }

    &__legal-links {
      justify-content: flex-start;
    }
  }
}
